fn array_split(a: Vec<i32>) -> (Vec<i32>, Vec<i32>) {
    let n = a.len();
    
    match n {
        0 => (vec![], vec![]),
        1 => (a, vec![]),  // or could be (vec![], a) - either satisfies requirements
        _ => {
            let split_point = n / 2;
            let first = a[..split_point].to_vec();
            let second = a[split_point..].to_vec();
            (first, second)
        }
    }
}